def transform(grid):
    """Extend the perpendicular edge of an object across a full 2-bar."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]

    # A full-length 2 bar is the divider; find the object touching either side.
    for horizontal in (True, False):
        length = w if horizontal else h
        cross = h if horizontal else w
        for axis in range(cross):
            bar = [(axis, k) if horizontal else (k, axis) for k in range(length)]
            if not all(grid[r][c] == 2 for r, c in bar):
                continue
            for side in (-1, 1):
                neighbor = axis + side
                if not 0 <= neighbor < cross:
                    continue
                adjacent = [((neighbor, k) if horizontal else (k, neighbor)) for k in range(length)]
                colors = {grid[r][c] for r, c in adjacent
                          if grid[r][c] not in (2, background)}
                if len(colors) != 1:
                    continue
                color = next(iter(colors))
                if not any(grid[r][c] == color for r, c in adjacent):
                    continue

                # Follow consecutive slices of the object's color away from the bar.
                pos = neighbor
                while 0 <= pos < cross:
                    slice_values = [grid[pos][k] if horizontal else grid[k][pos]
                                    for k in range(length)]
                    if color not in slice_values:
                        break
                    pos += side
                if 0 <= pos < cross:
                    for k in range(length):
                        r, c = (pos, k) if horizontal else (k, pos)
                        out[r][c] = 8
                return out
    return out


